package world.embers.qa;

import world.embers.*;
import world.embers.production.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.gametest.*;
import java.util.*;

@GameTestHolder(Embers.ID) @PrefixGameTestTemplate(false)
public class ProductionTests {
    @GameTest(template="empty") public static void flight_expiry_lands_safely_and_preserves_other_flight(GameTestHelper h){
        FakePlayer p=player(h);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);PlayerState s=new PlayerState();s.mouth=Brand.HETIANXIA.ordinal();s.lit=true;s.inhaleTotal=120;SmokingBenefits.tick(p,s);
        h.assertTrue(p.getAbilities().mayfly,"Brand grants flight");p.setOnGround(false);p.getAbilities().flying=true;p.setDeltaMovement(0,-1,0);SmokingBenefits.data(p).putInt("effect1",1);SmokingBenefits.tick(p,s);
        h.assertTrue(!p.getAbilities().mayfly&&!p.getAbilities().flying&&SmokingBenefits.data(p).getBoolean("landing")&&p.getDeltaMovement().y>=-.12,"Expiry releases flight and limits descent");
        p.setOnGround(true);SmokingBenefits.tick(p,s);h.assertTrue(!SmokingBenefits.data(p).getBoolean("landing")&&SmokingBenefits.data(p).getInt("cooldown1")==1200,"Cooldown begins after safe landing");
        FakePlayer other=player(h);other.getAbilities().mayfly=true;PlayerState another=new PlayerState();another.mouth=s.mouth;another.lit=true;another.inhaleTotal=120;SmokingBenefits.tick(other,another);SmokingBenefits.end(other,1);h.assertTrue(other.getAbilities().mayfly,"Existing flight ability is not revoked");h.succeed();
    }
    @GameTest(template="empty") public static void multiblock_break_refunds_once(GameTestHelper h){
        BlockPos pos=h.absolutePos(new BlockPos(1,1,1));var l=h.getLevel();var state=Production.MACHINE.get().defaultBlockState();
        l.setBlock(pos,state,3);Production.MACHINE.get().setPlacedBy(l,pos,state,player(h),new ItemStack(Production.MACHINE_ITEM.get()));
        ProcessingEntity m=(ProcessingEntity)l.getBlockEntity(pos);var r=m.recipes().get(0);fill(m,r,1);m.start();advance(m,123);
        l.destroyBlock(ProcessingBlock.part(pos,Direction.NORTH,5),true);
        for(int i=0;i<6;i++)h.assertTrue(!l.getBlockState(ProcessingBlock.part(pos,Direction.NORTH,i)).is(Production.MACHINE.get()),"Whole machine removed");
        var drops=l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(3));
        int machines=drops.stream().filter(e->e.getItem().is(Production.MACHINE_ITEM.get())).mapToInt(e->e.getItem().getCount()).sum();
        int raw=drops.stream().filter(e->r.tobacco.test(e.getItem())).mapToInt(e->e.getItem().getCount()).sum();
        h.assertTrue(machines==1&&raw==1,"Breaking upper end returns one machine and one reserved leaf");h.succeed();
    }
    @GameTest(template="empty") public static void rack_upper_break_preserves_contents(GameTestHelper h){
        var l=h.getLevel();BlockPos p=h.absolutePos(new BlockPos(1,1,1));l.setBlock(p.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);
        var state=Production.RACK.get().defaultBlockState();l.setBlock(p,state,3);Production.RACK.get().setPlacedBy(l,p,state,player(h),new ItemStack(Production.RACK_ITEM.get()));
        DryingRackEntity rack=(DryingRackEntity)l.getBlockEntity(p);rack.tobacco[0]=0;rack.progress[0]=.5;rack.tobacco[1]=1;rack.progress[1]=1;
        rack.load(rack.saveWithoutMetadata());h.assertTrue(rack.progress[0]==.5&&rack.progress[1]==1,"Drying progress survives reload");
        l.destroyBlock(p.above(),true);var drops=l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(p).inflate(2));
        h.assertTrue(l.getBlockState(p).isAir(),"Lower half removed");
        for(Item item:new Item[]{Production.RACK_ITEM.get(),Production.FRESH.get(Tobacco.RED).get(),Production.DRY.get(Tobacco.YELLOW).get()})h.assertTrue(drops.stream().filter(e->e.getItem().is(item)).mapToInt(e->e.getItem().getCount()).sum()==1,"One matching drop: "+item);
        h.succeed();
    }
    @GameTest(template="empty") public static void pressure_does_not_steal_foreign_effects(GameTestHelper h){
        FakePlayer p=player(h);var slow=net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN;
        p.addEffect(new net.minecraft.world.effect.MobEffectInstance(slow,40,0,false,false,false));PressureEffects.apply(p,slow,100,false);PressureEffects.clear(p);h.assertTrue(p.hasEffect(slow),"Even short foreign effects survive pressure disable");
        p.removeEffect(slow);PressureEffects.apply(p,slow,100,false);var saved=p.getEffect(slow).save(new CompoundTag());p.removeEffect(slow);p.addEffect(net.minecraft.world.effect.MobEffectInstance.load(saved));PressureEffects.clear(p);h.assertTrue(!p.hasEffect(slow),"Our ownership survives NBT reload");
        PressureEffects.apply(p,slow,100,false);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(slow,1000,1));PressureEffects.clear(p);h.assertTrue(p.hasEffect(slow)&&p.getEffect(slow).getAmplifier()==1,"Stronger external replacement is preserved");h.succeed();
    }
    static FakePlayer player(GameTestHelper h){return new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"ProductionTest"));}
    static ProcessingEntity machine(GameTestHelper h){BlockPos at=new BlockPos(1,1,1);h.setBlock(at,Production.MACHINE.get());return (ProcessingEntity)h.getBlockEntity(at);}
    static void fill(ProcessingEntity m,ProcessingRecipe r,int n){m.setItem(0,r.tobacco.getItems()[0].copyWithCount(n));m.setItem(1,new ItemStack(Items.LAVA_BUCKET));m.setItem(2,r.paper.getItems()[0].copyWithCount(n));for(int i=0;i<r.extras.size();i++)m.setItem(3+i,r.extras.get(i).ingredient().getItems()[0].copyWithCount(r.extras.get(i).count()*n));m.selected=r.getId().toString();}
    static void advance(ProcessingEntity m,int ticks){for(int i=0;i<ticks;i++)ProcessingEntity.tick(m.getLevel(),m.getBlockPos(),m.getBlockState(),m);}
    @GameTest(template="empty") public static void every_recipe_completes_and_consumes(GameTestHelper h){ProcessingEntity m=machine(h);List<ProcessingRecipe> all=m.recipes();h.assertTrue(all.size()==17,"Sixteen recipes and one green alternative must load");for(var r:all){m.running=false;m.clearContent();m.result=ItemStack.EMPTY;m.fuel=0;fill(m,r,1);h.assertTrue(m.start(),"Start "+r.getId());h.assertTrue(m.fuel==3&&m.getItem(8).isEmpty(),"No output before work completes");advance(m,5999);h.assertTrue(m.getItem(8).isEmpty(),"Five minute duration");advance(m,1);h.assertTrue(ItemStack.isSameItemSameTags(m.getItem(8),r.output)&&m.getItem(8).getCount()==1,"Output "+r.getId());h.assertTrue(!m.running&&m.result.isEmpty(),"No work without the next batch");int buckets=m.getItem(6).getCount()+m.getItem(7).getCount();h.assertTrue(buckets==(r.getId().getPath().endsWith("seven_stars")?2:1),"Lava/milk container returned");}h.succeed();}
    @GameTest(template="empty") public static void machine_locks_capability_and_refunds_on_stop(GameTestHelper h){ProcessingEntity m=machine(h);var r=m.recipes().stream().filter(x->x.getId().getPath().endsWith("double_happiness")).findFirst().orElseThrow();fill(m,r,2);h.assertTrue(m.start(),"Starts");var items=m.getCapability(ForgeCapabilities.ITEM_HANDLER).orElseThrow(IllegalStateException::new);for(int i=0;i<6;i++){h.assertTrue(items.extractItem(i,64,false).isEmpty(),"Cannot extract locked input "+i);ItemStack in=i==1?new ItemStack(Items.LAVA_BUCKET):new ItemStack(Items.PAPER);h.assertTrue(items.insertItem(i,in,false).getCount()==in.getCount(),"Cannot insert locked input "+i);}h.assertTrue(m.removeItem(0,1).isEmpty(),"Container API lock");advance(m,313);m.stop();h.assertTrue(m.getItem(0).getCount()==2&&m.getItem(2).getCount()==2&&m.getItem(3).getCount()==2,"Unfinished reservation returns exactly once");h.assertTrue(m.fuel==3&&m.work==0&&m.result.isEmpty(),"Spent fuel not refunded, no free progress");m.stop();h.assertTrue(m.getItem(0).getCount()==2,"Repeated stop cannot duplicate");h.assertTrue(items.extractItem(0,1,false).getCount()==1,"Unlocked after stop");h.succeed();}
    @GameTest(template="empty") public static void machine_save_reload_preserves_lock_and_reservation(GameTestHelper h){ProcessingEntity m=machine(h);var r=m.recipes().get(0);fill(m,r,1);m.start();advance(m,713);CompoundTag tag=m.saveWithoutMetadata();m.load(tag);h.assertTrue(m.running&&m.work==713&&m.fuel==3,"Load working state");m.stop();h.assertTrue(m.getItem(0).getCount()==1&&m.getItem(2).getCount()==1&&m.result.isEmpty(),"Refund survived reload");h.succeed();}
    @GameTest(template="empty") public static void machine_rejects_full_returns_and_wrong_additive(GameTestHelper h){ProcessingEntity m=machine(h);var r=m.recipes().get(0);fill(m,r,1);m.setItem(6,new ItemStack(Items.BUCKET,16));m.setItem(7,new ItemStack(Items.BUCKET,16));h.assertTrue(!m.start()&&m.fuel==0&&m.getItem(1).is(Items.LAVA_BUCKET)&&m.getItem(0).getCount()==1,"Full containers must reject before debit");m.setItem(6,ItemStack.EMPTY);m.setItem(7,ItemStack.EMPTY);m.setItem(5,new ItemStack(Items.DIAMOND));h.assertTrue(!m.start()&&m.getItem(5).is(Items.DIAMOND),"Unlisted additives cannot be swallowed");h.succeed();}
    @GameTest(template="empty") public static void completed_output_cannot_be_refunded_as_raw_material(GameTestHelper h){ProcessingEntity m=machine(h);var r=m.recipes().get(0);fill(m,r,1);m.start();m.setItem(8,new ItemStack(Items.STONE,10));advance(m,6000);h.assertTrue(!m.result.isEmpty()&&m.work==6000,"Finished batch waits for blocked output");m.stop();h.assertTrue(m.getItem(0).isEmpty()&&!m.result.isEmpty(),"Completed work does not also refund inputs");m.setItem(8,ItemStack.EMPTY);advance(m,1);h.assertTrue(m.getItem(8).getCount()==1&&m.result.isEmpty(),"Pending output delivered once");h.succeed();}
    @GameTest(template="empty") public static void duplicate_recipe_ingredients_need_separate_units(GameTestHelper h){ProcessingEntity m=machine(h);var r=new ProcessingRecipe(new ResourceLocation("embers","test"),Ingredient.of(Items.WHEAT),Ingredient.of(Items.PAPER),List.of(new ProcessingRecipe.Part(Ingredient.of(Items.SUGAR),1),new ProcessingRecipe.Part(Ingredient.of(Items.SUGAR),1)),new ItemStack(Items.APPLE),20,1);m.setItem(0,new ItemStack(Items.WHEAT));m.setItem(2,new ItemStack(Items.PAPER));m.setItem(3,new ItemStack(Items.SUGAR));h.assertTrue(!r.matches(m,h.getLevel()),"One sugar cannot satisfy two requirements");m.setItem(4,new ItemStack(Items.SUGAR));h.assertTrue(r.matches(m,h.getLevel()),"Two distinct sugar units match");h.succeed();}
    @GameTest(template="empty") public static void addiction_common_food_boundaries(GameTestHelper h){FakePlayer p=player(h);FoodRestriction.bind(p);p.getFoodData().setFoodLevel(5);p.getFoodData().setSaturation(0);SmokingBenefits.data(p).putInt("addiction",1000);p.eat(h.getLevel(),new ItemStack(Items.COOKED_BEEF));h.assertTrue(p.getFoodData().getFoodLevel()==5&&p.getFoodData().getSaturationLevel()==0,"Vanilla meal gives no nutrition");p.getFoodData().eat(10,1);p.getFoodData().setFoodLevel(20);p.getFoodData().setSaturation(20);h.assertTrue(p.getFoodData().getFoodLevel()==5&&p.getFoodData().getSaturationLevel()==0,"Cake and mod-style direct nutrition setters cannot restore food");p.eat(h.getLevel(),new ItemStack(Items.ROTTEN_FLESH));h.assertTrue(p.getFoodData().getFoodLevel()==9&&!p.hasEffect(net.minecraft.world.effect.MobEffects.HUNGER),"Rotten flesh remains edible without new hunger");p.getFoodData().eat(2,1);h.assertTrue(p.getFoodData().getFoodLevel()==9,"Rotten permission does not leak into later food calls");h.succeed();}
    @GameTest(template="empty") public static void sixteenth_distinct_cigarette_and_partial_roundtrip(GameTestHelper h){FakePlayer p=player(h);PlayerState s=new PlayerState();for(int i=0;i<15;i++){s.freshCigarette();s.mouth=Brand.HEHUA.ordinal();s.lit=true;s.inhaleTotal=120;SmokingBenefits.tick(p,s);}h.assertTrue(!SmokingBenefits.addicted(p),"First fifteen do not trigger addiction");for(int i=0;i<30;i++)SmokingBenefits.tick(p,s);h.assertTrue(SmokingBenefits.data(p).getInt("daily")==15,"Same cigarette counts once");CompoundTag n=new CompoundTag();s.writeCigarette(n);PlayerState reloaded=new PlayerState();reloaded.readCigarette(n);reloaded.mouth=s.mouth;reloaded.lit=true;reloaded.inhaleTotal=120;SmokingBenefits.tick(p,reloaded);h.assertTrue(!SmokingBenefits.addicted(p),"Returning partial cigarette does not count twice");s.freshCigarette();s.inhaleTotal=120;SmokingBenefits.tick(p,s);h.assertTrue(SmokingBenefits.data(p).getInt("addiction")==72000,"Sixteenth starts exactly one hour");s.freshCigarette();s.inhaleTotal=120;SmokingBenefits.tick(p,s);h.assertTrue(SmokingBenefits.data(p).getInt("addiction")==71999,"More cigarettes do not extend the timer");h.succeed();}
    @GameTest(template="empty") public static void satiation_six_pulses_and_cooldown(GameTestHelper h){FakePlayer p=player(h);p.getFoodData().setFoodLevel(3);p.getFoodData().setSaturation(0);PlayerState s=new PlayerState();s.mouth=Brand.ZHONGHUA.ordinal();s.lit=true;s.inhaleTotal=120;for(int i=0;i<1200;i++)SmokingBenefits.tick(p,s);h.assertTrue(p.getFoodData().getFoodLevel()==9,"Six pulses, first only after ten seconds");h.assertTrue(!SmokingBenefits.active(p,3)&&SmokingBenefits.data(p).getInt("cooldown3")==1200,"Effect ends with a full one-minute cooldown");h.succeed();}
    @GameTest(template="empty") public static void unopened_stack_splits_only_one_pack(GameTestHelper h){FakePlayer p=player(h);ItemStack packs=new ItemStack(Embers.PACKS.get(Brand.CHAPMAN).get(),10);p.setItemInHand(InteractionHand.MAIN_HAND,packs);h.assertTrue(packs.getMaxStackSize()==10&&!SmokingItem.take(packs),"Cannot mutate a whole stack");h.assertTrue(PackHandling.isolate(p)&&p.getMainHandItem().getCount()==1,"Separate one pack");h.assertTrue(SmokingItem.take(p.getMainHandItem())&&p.getMainHandItem().getMaxStackSize()==1,"Opened pack becomes nonstackable");h.assertTrue(p.getInventory().getItem(1).getCount()==9&&SmokingItem.remaining(p.getInventory().getItem(1))==10,"Other nine remain unopened");h.succeed();}
    @GameTest(template="empty") public static void crop_mature_and_immature_loot(GameTestHelper h){for(Tobacco t:Tobacco.values()){TobaccoCrop crop=(TobaccoCrop)Production.CROPS.get(t).get();for(int age:new int[]{0,7}){var state=crop.getStateForAge(age);var loot=net.minecraft.world.level.block.Block.getDrops(state,h.getLevel(),h.absolutePos(new BlockPos(2,1,2)),null,player(h),new ItemStack(Items.DIAMOND_HOE));int seed=loot.stream().filter(x->x.is(Production.SEEDS.get(t).get())).mapToInt(ItemStack::getCount).sum(),fresh=loot.stream().filter(x->x.is(Production.FRESH.get(t).get())).mapToInt(ItemStack::getCount).sum();h.assertTrue(seed==(age==7?2:1)&&fresh==(age==7?3:0),"Harvest yield "+t+" age "+age);}}h.succeed();}
}
